-- Agnipa Memorial Park — deceased registry
-- Generated from Docs/Agnipa_Cemetery_Names_and_Death_Dates.xlsx (489 records).
-- Run once in Supabase Dashboard -> SQL Editor.
--
-- This is a REGISTRY table: it stores the names + dates of death exactly as they
-- appear in the source sheet (plus a best-effort parsed date/year), so it can be
-- searched and later linked to map placements in public.graves. It does NOT
-- touch the existing graves/section/route data.

create table if not exists public.deceased (
  id                 bigint generated by default as identity primary key,
  record_no          integer,                 -- "No." column from the sheet (blank for 34 rows)
  name               text not null,           -- "SURNAME, FIRSTNAME" as written
  surname            text,                    -- text before the first comma
  given_name         text,                    -- text after the first comma
  dod_raw            text,                    -- Date of Death, exactly as written
  dod_date           date,                    -- parsed full date, when unambiguous
  dod_year           integer,                 -- parsed year (or range start)
  status             text not null default 'deceased'
                       check (status in ('deceased','reserved','unknown')),
  remarks            text,                    -- original sheet remarks / data-quality notes
  needs_verification boolean not null default false,
  source_file        text default 'Agnipa_Cemetery_Names_and_Death_Dates.xlsx',
  created_at         timestamptz not null default now()
);

create index if not exists idx_deceased_name on public.deceased (lower(name));
create index if not exists idx_deceased_surname on public.deceased (lower(surname));
create index if not exists idx_deceased_dod_year on public.deceased (dod_year);
create index if not exists idx_deceased_status on public.deceased (status);
create index if not exists idx_deceased_needs_verification
  on public.deceased (needs_verification) where needs_verification;

alter table public.deceased enable row level security;

drop policy if exists "Anyone can view deceased" on public.deceased;
create policy "Anyone can view deceased"
  on public.deceased for select
  to anon, authenticated
  using (true);

drop policy if exists "Anyone can add deceased" on public.deceased;
create policy "Anyone can add deceased"
  on public.deceased for insert
  to anon, authenticated
  with check (true);

drop policy if exists "Anyone can update deceased" on public.deceased;
create policy "Anyone can update deceased"
  on public.deceased for update
  to anon, authenticated
  using (true)
  with check (true);

-- Idempotency: clear the generated seed before re-inserting so this file can be
-- re-run safely. Comment this line out to *append* instead.
delete from public.deceased where source_file = 'Agnipa_Cemetery_Names_and_Death_Dates.xlsx';


